package cli

import (
	"bytes"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/jsonutil"
)

// managedFilePerm is the mode a managed-block file is created with. Both files
// harnaas contributes a block to — the project's memory file and its
// version-control ignore file — are committed, hand-edited text, so the
// ordinary non-executable default.
const managedFilePerm fs.FileMode = 0o644

// managedBlock is a marker-delimited region harnaas owns inside a file the team
// also writes.
//
// The two markers are whole lines. Matching a whole line rather than a prefix
// is what stops a marker quoted inside a fenced code block, or an indented one
// inside a list item, from being read as the start of harnaas's region — the
// same rule the frontmatter reader applies to its closing delimiter, and for
// the same reason: the file's author is allowed to write about harnaas.
//
// The comment syntax is a field rather than a constant because the two files
// that carry a block do not share one: a memory file is Markdown and takes an
// HTML comment, an ignore file takes a `#` line. Everything else about editing
// a block is identical, which is why there is one editor and not two.
type managedBlock struct {
	// begin is the line that opens the region.
	begin string

	// end is the line that closes it.
	end string
}

// htmlManagedBlock returns the block named name, delimited by HTML comments.
func htmlManagedBlock(name string) managedBlock {
	return managedBlock{
		begin: "<!-- harnaas:begin " + name + " -->",
		end:   "<!-- harnaas:end " + name + " -->",
	}
}

// blockSpan is where a managed block sits in a file's bytes: from the first
// byte of the begin marker's line to one past the newline that ends the end
// marker's line, so replacing the span replaces the whole region and nothing
// around it.
type blockSpan struct {
	start int
	end   int
	found bool
}

// locateManagedBlock finds b in content.
//
// A file with no block at all is not a failure — it is the ordinary case on a
// first install, and the state a removal converges on. What is a failure is a
// file whose markers do not pair up: harnaas would have to guess where its
// region ends, and every guess either swallows somebody's writing or leaves a
// marker behind that the next run reads differently again.
func locateManagedBlock(file string, content []byte, b managedBlock) (blockSpan, error) {
	var span blockSpan
	open := -1

	for offset := 0; offset < len(content); {
		line, next := lineAt(content, offset)

		switch {
		case matchesMarker(line, b.begin):
			if open >= 0 || span.found {
				return blockSpan{}, &managedBlockError{File: file, Reason: blockDuplicated, Marker: b.begin}
			}
			open = offset
		case matchesMarker(line, b.end):
			if open < 0 {
				return blockSpan{}, &managedBlockError{File: file, Reason: blockUnopened, Marker: b.end}
			}
			span = blockSpan{start: open, end: next, found: true}
			open = -1
		}

		offset = next
	}

	if open >= 0 {
		return blockSpan{}, &managedBlockError{File: file, Reason: blockUnclosed, Marker: b.begin}
	}

	return span, nil
}

// lineAt returns the line beginning at offset and the offset the next line
// begins at, which is one past the newline or the end of the content for a
// final line that has none.
func lineAt(content []byte, offset int) (line string, next int) {
	if end := bytes.IndexByte(content[offset:], '\n'); end >= 0 {
		return string(content[offset : offset+end]), offset + end + 1
	}
	return string(content[offset:]), len(content)
}

// matchesMarker reports whether line is the marker.
//
// Trailing horizontal whitespace and a carriage return are ignored, so a file
// with CRLF endings and one an editor trimmed differently are both recognized.
// Leading whitespace is not: an indented marker is inside somebody's list or
// code block, not harnaas's.
func matchesMarker(line, marker string) bool {
	return strings.TrimRight(line, " \t\r") == marker
}

// setManagedBlock returns content with b's body replaced by body, appending the
// whole block where content does not have one.
//
// Everything outside the markers is carried through byte for byte. Where the
// block is appended, the only addition to the previous content is the newline a
// file not ending in one needs before a marker can begin a line — and the block
// is appended with no blank line before it deliberately, so that removing it
// again restores the previous bytes exactly rather than leaving a blank line
// behind for the next install to append a second one after.
func setManagedBlock(file string, content []byte, b managedBlock, body []byte) ([]byte, error) {
	span, err := locateManagedBlock(file, content, b)
	if err != nil {
		return nil, err
	}

	rendered := renderManagedBlock(b, body)

	if !span.found {
		if len(content) == 0 {
			return rendered, nil
		}
		updated := make([]byte, 0, len(content)+len(rendered)+1)
		updated = append(updated, content...)
		if content[len(content)-1] != '\n' {
			updated = append(updated, '\n')
		}
		return append(updated, rendered...), nil
	}

	updated := make([]byte, 0, span.start+len(rendered)+len(content)-span.end)
	updated = append(updated, content[:span.start]...)
	updated = append(updated, rendered...)
	return append(updated, content[span.end:]...), nil
}

// removeManagedBlock returns content with b and both its markers gone.
//
// Content with no block comes back unchanged rather than as a failure: removal
// is what every run with nothing to contribute does, and most of those runs
// meet a file that never had a block.
func removeManagedBlock(file string, content []byte, b managedBlock) ([]byte, error) {
	span, err := locateManagedBlock(file, content, b)
	if err != nil {
		return nil, err
	}
	if !span.found {
		return content, nil
	}

	updated := make([]byte, 0, len(content)-(span.end-span.start))
	updated = append(updated, content[:span.start]...)
	return append(updated, content[span.end:]...), nil
}

// renderManagedBlock is the block as it appears in a file: the begin marker,
// the body, the end marker, each on its own line.
//
// A body not ending in a newline is given one, because the end marker has to
// begin a line for the next run to recognize it. An empty body produces the two
// markers with nothing between them, which is a block harnaas owns and has
// nothing to put in — distinct from no block at all, and reached only by a
// caller that asked for it.
func renderManagedBlock(b managedBlock, body []byte) []byte {
	var out bytes.Buffer
	out.WriteString(b.begin)
	out.WriteByte('\n')
	if len(body) > 0 {
		out.Write(body)
		if body[len(body)-1] != '\n' {
			out.WriteByte('\n')
		}
	}
	out.WriteString(b.end)
	out.WriteByte('\n')
	return out.Bytes()
}

// writeManagedBlock puts body inside b's markers in the file named name under
// the project root, creating the file when it is absent.
//
// A run that would write the bytes already there writes nothing at all. The
// content is what matters, so an unchanged file with an unchanged modification
// time is the honest record of a run that changed nothing — and it keeps a
// re-run out of every file watcher the team has pointed at their memory file.
func writeManagedBlock(root, name string, b managedBlock, body []byte) error {
	content, err := readManagedFile(root, name)
	if err != nil {
		return err
	}

	updated, err := setManagedBlock(name, content, b, body)
	if err != nil {
		return err
	}
	if bytes.Equal(updated, content) {
		return nil
	}

	return writeManagedFile(root, name, updated)
}

// dropManagedBlock removes b's block from the file named name under the project
// root.
//
// An absent file, and a file that never carried the block, are both nothing to
// do. The file is left in place even where the block was the whole of it: what
// harnaas owns is the region between its markers, and the empty file that
// remains is a file the team can delete in one keystroke, where a file harnaas
// deleted is content nobody can get back from the manifest.
func dropManagedBlock(root, name string, b managedBlock) error {
	content, err := readManagedFile(root, name)
	if err != nil {
		return err
	}

	updated, err := removeManagedBlock(name, content, b)
	if err != nil {
		return err
	}
	if bytes.Equal(updated, content) {
		return nil
	}

	return writeManagedFile(root, name, updated)
}

// readManagedFile reads the file, reporting an absent one as empty content.
//
// "Not there yet" is the first-install case for every file that carries a
// block, and treating it as empty is what makes creating one the same code path
// as editing one.
func readManagedFile(root, name string) ([]byte, error) {
	content, err := os.ReadFile(filepath.Join(root, name))
	if errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", name, err)
	}
	return content, nil
}

// writeManagedFile replaces the file's contents atomically.
//
// The write goes through jsonutil despite the package name and the file being
// Markdown or an ignore list: WriteFileAtomic takes arbitrary bytes and is the
// module's one atomic writer, and a second implementation would be a second
// place the stage-sync-rename sequence has to stay correct.
func writeManagedFile(root, name string, content []byte) error {
	if err := jsonutil.WriteFileAtomic(filepath.Join(root, name), content, managedFilePerm); err != nil {
		return fmt.Errorf("write %s: %w", name, err)
	}
	return nil
}

// blockMarkerReason is why harnaas will not edit a file's managed block.
type blockMarkerReason string

const (
	// blockUnclosed is an opening marker with no closing one after it.
	blockUnclosed blockMarkerReason = "unclosed"

	// blockUnopened is a closing marker with no opening one before it.
	blockUnopened blockMarkerReason = "unopened"

	// blockDuplicated is a second opening marker in one file.
	blockDuplicated blockMarkerReason = "duplicated"
)

// managedBlockError refuses to edit a file whose markers do not pair up.
//
// The three reasons are one type because the reader's next action is the same
// in all three — open the file and look at the marker lines — and the message
// says which of them is there. What harnaas will not do is repair the markers
// itself: every repair is a guess about where the region the team can edit
// begins, and a wrong guess overwrites their writing with a block.
type managedBlockError struct {
	// File is the file, named the way the reader sees it: relative to the
	// project root.
	File string

	// Reason is which of the three shapes the markers are in.
	Reason blockMarkerReason

	// Marker is the marker line the reason is about.
	Marker string
}

func (e *managedBlockError) Error() string {
	var problem string
	switch e.Reason {
	case blockUnclosed:
		problem = fmt.Sprintf("%s opens a harnaas managed block with %s and never closes it", e.File, e.Marker)
	case blockUnopened:
		problem = fmt.Sprintf("%s closes a harnaas managed block with %s that was never opened", e.File, e.Marker)
	case blockDuplicated:
		problem = fmt.Sprintf("%s opens a harnaas managed block with %s more than once", e.File, e.Marker)
	}

	return problem + "\n\n" +
		fmt.Sprintf("Edit %s so the block appears once, opened and closed by its own marker line, "+
			"or delete the marker lines entirely and re-run to have harnaas write the block again.", e.File)
}

package cli

import (
	"bytes"
	"cmp"
	"fmt"
	"slices"
)

// memoryFileName is the project's committed memory file — the file a harness
// reads for always-on guidance without anybody having run install.
//
// `AGENTS.md` rather than any harness's own file: it is the one memory file
// several harnesses already read, and the harness whose file it is not reaches
// it through a bridge line. That is also what makes an instruction distinct
// from a rule at all — an instruction survives a fresh clone because it lives
// in a committed file, and a rule does not because it lives in an installed
// one.
const memoryFileName = "AGENTS.md"

// instructionBlock is the region harnaas owns inside the memory file.
//
// The name in the markers is `instructions` rather than a bare `harnaas`,
// because the ignore file's block is harnaas's too and a reader meeting one
// marker should not have to know which of harnaas's blocks it delimits.
var instructionBlock = htmlManagedBlock("instructions")

// instruction is one instruction asset's contribution to the memory file.
//
// It carries the source alongside the content because the block is committed:
// a reader opening `AGENTS.md` months later meets text nobody on the team
// wrote, and the comment above it is the only thing in the file that says where
// it came from.
type instruction struct {
	// ID is the asset's id, which is what the block is ordered by.
	ID string

	// Source is the asset's source spelled the way the manifest declares it.
	Source string

	// Content is the asset's bytes, inlined verbatim.
	Content []byte
}

// renderInstructionBlock is the body of the memory file's managed block.
//
// The ordering is by asset id and not by manifest position, so moving an entry
// in `harnaas.json` regenerates a byte-identical block: the manifest's order
// says nothing about what the assets mean, and a diff that moved a thousand
// lines because somebody sorted their manifest would be a diff nobody reads.
//
// Content is inlined verbatim. The one byte that may be added is a newline
// after content that does not end in one, because the next asset's comment has
// to begin a line — every other byte of every asset arrives in the file exactly
// as it resolved.
func renderInstructionBlock(instructions []instruction) []byte {
	ordered := slices.Clone(instructions)
	slices.SortStableFunc(ordered, func(a, b instruction) int {
		return cmp.Compare(a.ID, b.ID)
	})

	var body bytes.Buffer
	for i, entry := range ordered {
		if i > 0 {
			body.WriteByte('\n')
		}
		fmt.Fprintf(&body, "<!-- harnaas instruction %q from %s -->\n", entry.ID, entry.Source)
		body.Write(entry.Content)
		if len(entry.Content) > 0 && entry.Content[len(entry.Content)-1] != '\n' {
			body.WriteByte('\n')
		}
	}

	return body.Bytes()
}

// writeInstructionBlock makes the memory file's managed block hold exactly
// these instruction assets, and removes the block when there are none.
//
// The empty case is a removal rather than an empty block on purpose: a block
// with nothing in it is a claim that harnaas has something to say here, and the
// state after the last instruction asset goes is that it does not.
func writeInstructionBlock(root string, instructions []instruction) error {
	if len(instructions) == 0 {
		return dropManagedBlock(root, memoryFileName, instructionBlock)
	}
	return writeManagedBlock(root, memoryFileName, instructionBlock, renderInstructionBlock(instructions))
}

package cli

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// hashBlock is a second comment syntax, declared here rather than in the
// package because no file harnaas writes today takes one. It exists so the
// editor's reusability is exercised rather than asserted: every rule below that
// runs against the HTML block runs against a block whose markers share none of
// its characters.
func hashBlock(name string) managedBlock {
	return managedBlock{
		begin: "# harnaas:begin " + name,
		end:   "# harnaas:end " + name,
	}
}

const testFile = "MEMORY.md"

func TestSetManagedBlockCreatesTheWholeFileWhenThereIsNoContent(t *testing.T) {
	t.Parallel()

	block := htmlManagedBlock("instructions")

	updated, err := setManagedBlock(testFile, nil, block, []byte("body\n"))
	require.NoError(t, err)

	assert.Equal(t, []string{
		"<!-- harnaas:begin instructions -->",
		"body",
		"<!-- harnaas:end instructions -->",
		"",
	}, strings.Split(string(updated), "\n"))
}

func TestSetManagedBlockAppendsBeneathExistingContent(t *testing.T) {
	t.Parallel()

	block := htmlManagedBlock("instructions")
	content := []byte("# Agents\n\nHand written.\n")

	updated, err := setManagedBlock(testFile, content, block, []byte("body\n"))
	require.NoError(t, err)

	assert.True(t, strings.HasPrefix(string(updated), string(content)),
		"the previous content must survive byte for byte at the head of the file")
	assert.Equal(t, []string{
		"# Agents",
		"",
		"Hand written.",
		"<!-- harnaas:begin instructions -->",
		"body",
		"<!-- harnaas:end instructions -->",
		"",
	}, strings.Split(string(updated), "\n"))
}

func TestSetManagedBlockGivesAFileWithNoFinalNewlineOne(t *testing.T) {
	t.Parallel()

	block := htmlManagedBlock("instructions")

	updated, err := setManagedBlock(testFile, []byte("no newline"), block, []byte("body\n"))
	require.NoError(t, err)

	assert.Equal(t, []string{
		"no newline",
		"<!-- harnaas:begin instructions -->",
		"body",
		"<!-- harnaas:end instructions -->",
		"",
	}, strings.Split(string(updated), "\n"))
}

func TestSetManagedBlockRewritesOnlyTheRegionBetweenTheMarkers(t *testing.T) {
	t.Parallel()

	block := htmlManagedBlock("instructions")
	content := []byte(
		"# Agents\n" +
			"\n" +
			"Before.\n" +
			"<!-- harnaas:begin instructions -->\n" +
			"stale\n" +
			"<!-- harnaas:end instructions -->\n" +
			"\n" +
			"After.\n",
	)

	updated, err := setManagedBlock(testFile, content, block, []byte("fresh\n"))
	require.NoError(t, err)

	assert.Equal(t, []string{
		"# Agents",
		"",
		"Before.",
		"<!-- harnaas:begin instructions -->",
		"fresh",
		"<!-- harnaas:end instructions -->",
		"",
		"After.",
		"",
	}, strings.Split(string(updated), "\n"))
}

func TestSetManagedBlockLeavesAMarkerThatDoesNotStandAlone(t *testing.T) {
	t.Parallel()

	block := htmlManagedBlock("instructions")
	// The marker is quoted in prose and indented inside a list item. Neither is
	// harnaas's region, and reading either as one would put a block in the
	// middle of somebody's sentence.
	content := []byte(
		"Write <!-- harnaas:begin instructions --> to open the block.\n" +
			"\n" +
			"- Example: <!-- harnaas:begin instructions -->\n",
	)

	updated, err := setManagedBlock(testFile, content, block, []byte("body\n"))
	require.NoError(t, err)

	assert.True(t, strings.HasPrefix(string(updated), string(content)))
	assert.Equal(t, 1, strings.Count(string(updated), "\n<!-- harnaas:begin instructions -->\n"),
		"exactly one marker stands on a line of its own: the one harnaas just appended")
}

func TestSetManagedBlockAcceptsCarriageReturnsAndTrailingSpacesOnAMarker(t *testing.T) {
	t.Parallel()

	block := htmlManagedBlock("instructions")
	content := []byte(
		"Before.\r\n" +
			"<!-- harnaas:begin instructions -->  \r\n" +
			"stale\r\n" +
			"<!-- harnaas:end instructions -->\r\n" +
			"After.\r\n",
	)

	updated, err := setManagedBlock(testFile, content, block, []byte("fresh\n"))
	require.NoError(t, err)

	assert.Equal(t, "Before.\r\n"+
		"<!-- harnaas:begin instructions -->\n"+
		"fresh\n"+
		"<!-- harnaas:end instructions -->\n"+
		"After.\r\n", string(updated))
}

func TestSetManagedBlockTerminatesABodyThatDoesNotEndInANewline(t *testing.T) {
	t.Parallel()

	block := htmlManagedBlock("instructions")

	updated, err := setManagedBlock(testFile, nil, block, []byte("body"))
	require.NoError(t, err)

	assert.Equal(t, "<!-- harnaas:begin instructions -->\nbody\n<!-- harnaas:end instructions -->\n",
		string(updated))
}

func TestSetManagedBlockWithAnEmptyBodyWritesTheMarkersAlone(t *testing.T) {
	t.Parallel()

	block := htmlManagedBlock("instructions")

	updated, err := setManagedBlock(testFile, nil, block, nil)
	require.NoError(t, err)

	assert.Equal(t, "<!-- harnaas:begin instructions -->\n<!-- harnaas:end instructions -->\n",
		string(updated))
}

func TestManagedBlockRoundTripRestoresTheOriginalBytes(t *testing.T) {
	t.Parallel()

	for _, block := range []managedBlock{htmlManagedBlock("instructions"), hashBlock("installed")} {
		original := []byte("# Agents\n\nHand written.\n")

		withBlock, err := setManagedBlock(testFile, original, block, []byte("body\n"))
		require.NoError(t, err)
		require.NotEqual(t, string(original), string(withBlock))

		restored, err := removeManagedBlock(testFile, withBlock, block)
		require.NoError(t, err)

		// The block is appended with no separating blank line precisely so this
		// holds: an install followed by an uninstall leaves the file the team
		// wrote, not the file plus whatever harnaas used as spacing.
		assert.Equal(t, string(original), string(restored))
	}
}

func TestRemoveManagedBlockKeepsEverythingAroundIt(t *testing.T) {
	t.Parallel()

	block := hashBlock("installed")
	content := []byte(
		"node_modules/\n" +
			"# harnaas:begin installed\n" +
			"/.claude/rules/review.md\n" +
			"# harnaas:end installed\n" +
			"*.log\n",
	)

	updated, err := removeManagedBlock(testFile, content, block)
	require.NoError(t, err)

	assert.Equal(t, "node_modules/\n*.log\n", string(updated))
}

func TestRemoveManagedBlockLeavesAFileWithNoBlockAlone(t *testing.T) {
	t.Parallel()

	content := []byte("# Agents\n")

	updated, err := removeManagedBlock(testFile, content, htmlManagedBlock("instructions"))
	require.NoError(t, err)

	assert.Equal(t, string(content), string(updated))
}

func TestManagedBlockRefusesMarkersThatDoNotPairUp(t *testing.T) {
	t.Parallel()

	block := htmlManagedBlock("instructions")

	tests := []struct {
		name    string
		content string
		reason  blockMarkerReason
		marker  string
	}{
		{
			name:    "opened and never closed",
			content: "before\n<!-- harnaas:begin instructions -->\nbody\n",
			reason:  blockUnclosed,
			marker:  block.begin,
		},
		{
			name:    "closed without being opened",
			content: "body\n<!-- harnaas:end instructions -->\n",
			reason:  blockUnopened,
			marker:  block.end,
		},
		{
			name: "opened twice",
			content: "<!-- harnaas:begin instructions -->\na\n<!-- harnaas:end instructions -->\n" +
				"<!-- harnaas:begin instructions -->\nb\n<!-- harnaas:end instructions -->\n",
			reason: blockDuplicated,
			marker: block.begin,
		},
		{
			name:    "opened again before being closed",
			content: "<!-- harnaas:begin instructions -->\n<!-- harnaas:begin instructions -->\n",
			reason:  blockDuplicated,
			marker:  block.begin,
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()

			for operation, run := range map[string]func() ([]byte, error){
				"set": func() ([]byte, error) {
					return setManagedBlock(testFile, []byte(test.content), block, []byte("body\n"))
				},
				"remove": func() ([]byte, error) {
					return removeManagedBlock(testFile, []byte(test.content), block)
				},
			} {
				updated, err := run()
				assert.Nil(t, updated, "%s must produce no content at all when it refuses", operation)

				var blockErr *managedBlockError
				require.ErrorAs(t, err, &blockErr)
				assert.Equal(t, test.reason, blockErr.Reason)
				assert.Equal(t, test.marker, blockErr.Marker)
				assert.Equal(t, testFile, blockErr.File)
			}
		})
	}
}

func TestManagedBlockErrorStatesTheProblemThenTheFix(t *testing.T) {
	t.Parallel()

	for _, reason := range []blockMarkerReason{blockUnclosed, blockUnopened, blockDuplicated} {
		err := &managedBlockError{File: memoryFileName, Reason: reason, Marker: "<!-- harnaas:begin instructions -->"}

		parts := strings.SplitN(err.Error(), "\n\n", 2)
		require.Len(t, parts, 2, "a diagnostic is a problem, a blank line and a fix")
		assert.Contains(t, parts[0], memoryFileName)
		assert.Contains(t, parts[1], "Edit "+memoryFileName,
			"the remedy is an edit to the file the reader has open")
		assert.NotContains(t, parts[1], "`", "no remedy offers a command that repairs the markers for them")
	}
}

func TestWriteManagedBlockCreatesTheFileWhenItIsAbsent(t *testing.T) {
	t.Parallel()

	root := t.TempDir()
	block := htmlManagedBlock("instructions")

	require.NoError(t, writeManagedBlock(root, memoryFileName, block, []byte("body\n")))

	content, err := os.ReadFile(filepath.Join(root, memoryFileName))
	require.NoError(t, err)
	assert.Equal(t, "<!-- harnaas:begin instructions -->\nbody\n<!-- harnaas:end instructions -->\n",
		string(content))
}

func TestWriteManagedBlockLeavesAnUnchangedFileUntouched(t *testing.T) {
	t.Parallel()

	root := t.TempDir()
	path := filepath.Join(root, memoryFileName)
	block := htmlManagedBlock("instructions")

	require.NoError(t, writeManagedBlock(root, memoryFileName, block, []byte("body\n")))

	before, err := os.Stat(path)
	require.NoError(t, err)

	require.NoError(t, writeManagedBlock(root, memoryFileName, block, []byte("body\n")))

	after, err := os.Stat(path)
	require.NoError(t, err)
	assert.Equal(t, before.ModTime(), after.ModTime(),
		"a run that would write the bytes already there must not write at all")
}

func TestWriteManagedBlockLeavesNoStagingFileBehind(t *testing.T) {
	t.Parallel()

	root := t.TempDir()

	require.NoError(t, writeManagedBlock(root, memoryFileName, htmlManagedBlock("instructions"), []byte("body\n")))

	entries, err := os.ReadDir(root)
	require.NoError(t, err)
	names := make([]string, 0, len(entries))
	for _, entry := range entries {
		names = append(names, entry.Name())
	}
	assert.Equal(t, []string{memoryFileName}, names)
}

func TestDropManagedBlockOnAnAbsentFileCreatesNothing(t *testing.T) {
	t.Parallel()

	root := t.TempDir()

	require.NoError(t, dropManagedBlock(root, memoryFileName, htmlManagedBlock("instructions")))

	entries, err := os.ReadDir(root)
	require.NoError(t, err)
	assert.Empty(t, entries, "removing a block from a file that is not there must not create one")
}

func TestDropManagedBlockKeepsTheFileWhenTheBlockWasAllOfIt(t *testing.T) {
	t.Parallel()

	root := t.TempDir()
	block := htmlManagedBlock("instructions")

	require.NoError(t, writeManagedBlock(root, memoryFileName, block, []byte("body\n")))
	require.NoError(t, dropManagedBlock(root, memoryFileName, block))

	content, err := os.ReadFile(filepath.Join(root, memoryFileName))
	require.NoError(t, err)
	assert.Empty(t, content, "what harnaas owns is the region between its markers, not the file")
}

func TestWriteManagedBlockRefusesAFileWhoseMarkersDoNotPairUp(t *testing.T) {
	t.Parallel()

	root := t.TempDir()
	path := filepath.Join(root, memoryFileName)
	original := "before\n<!-- harnaas:begin instructions -->\nbody\n"
	require.NoError(t, os.WriteFile(path, []byte(original), managedFilePerm))

	err := writeManagedBlock(root, memoryFileName, htmlManagedBlock("instructions"), []byte("fresh\n"))

	var blockErr *managedBlockError
	require.ErrorAs(t, err, &blockErr)
	assert.Equal(t, memoryFileName, blockErr.File)

	content, readErr := os.ReadFile(path)
	require.NoError(t, readErr)
	assert.Equal(t, original, string(content), "a refusal writes nothing")
}

