func locateManagedBlock(file string, content []byte, b managedBlock) (blockSpan, error) {
	var span blockSpan
	open := -1

	for offset := 0; offset < len(content); {
		line, next := lineAt(content, offset)

		switch {
		case matchesMarker(line, b.begin):
			if open >= 0 || span.found {
				return blockSpan{}, &managedBlockError{File: file, Reason: blockDuplicated, Marker: b.begin}
